import os
import sys
import time
import webbrowser
from datetime import datetime

LOG_DIR = "./target"
LOG_FILE = "reminder_tool.log"

def log_message(message):
    try:
        os.makedirs(LOG_DIR, exist_ok=True)
        with open(os.path.join(LOG_DIR, LOG_FILE), "a") as log_file:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            log_file.write(f"[{timestamp}] {message}\n")
    except Exception as e:
        print(f"Error: Unable to write to log file. {e}", file=sys.stderr)

def open_url(url):
    try:
        if webbrowser.open(url):
            log_message(f"Successfully opened URL: {url}")
            print(f"Successfully opened URL: {url}")
        else:
            log_message(f"Failed to open URL: {url}")
            print(f"Failed to open URL: {url}", file=sys.stderr)
    except Exception as e:
        log_message(f"Error: Could not open URL {url}. Exception: {e}")
        print(f"Error: Could not open URL. {e}", file=sys.stderr)

def detach_process():
    if os.name != 'nt':
        # Detach from terminal on Unix-like systems
        try:
            pid = os.fork()
            if pid > 0:
                sys.exit(0)  # Parent process exits
        except OSError as e:
            print(f"Error: Unable to fork process. {e}", file=sys.stderr)
            sys.exit(1)
        os.setsid()
        pid = os.fork()
        if pid > 0:
            sys.exit(0)  # Parent process exits
        sys.stdout.flush()
        sys.stderr.flush()
        with open(os.devnull, 'r') as devnull:
            os.dup2(devnull.fileno(), sys.stdin.fileno())
        with open(os.devnull, 'a') as devnull:
            os.dup2(devnull.fileno(), sys.stdout.fileno())
            os.dup2(devnull.fileno(), sys.stderr.fileno())

def main():
    if len(sys.argv) < 2 or len(sys.argv) > 4:
        print("Usage: python script.py <URL> [interval_seconds] [attempts]", file=sys.stderr)
        log_message("Error: Incorrect number of arguments provided.")
        sys.exit(1)

    url = sys.argv[1]
    interval = int(sys.argv[2]) if len(sys.argv) >= 3 else 3600
    attempts = int(sys.argv[3]) if len(sys.argv) == 4 else 1

    detach_process()

    for attempt in range(attempts):
        log_message(f"Attempt {attempt + 1} to open URL: {url}")
        open_url(url)
        if attempt < attempts - 1:
            time.sleep(interval)

if __name__ == "__main__":
    main()

